"use client";

import { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { Map as MaplibreMap, Marker, NavigationControl, Source, Layer } from "react-map-gl/maplibre";
import "maplibre-gl/dist/maplibre-gl.css";

// Ported from the standalone Vite prototype. Only the two `import.meta.env`
// reads changed (Vite → Next public env) plus a cleanup on the palette effect
// below; the map, the contribution flows and the styling are untouched.
const MAPTILER_KEY = process.env.NEXT_PUBLIC_MAPTILER_KEY;
const styleFor = (id) => {
  const k = MAPTILER_KEY;
  const u = (slug) => `https://api.maptiler.com/maps/${slug}/style.json?key=${k}`;
  switch (id) {
    case "firefly":     return u("topo-v2-dark");
    case "aurora":      return u("streets-v2-dark");
    case "watercolor":  return u("aquarelle");
    case "tidal":       return u("ocean");
    case "sumie":       return u("toner-v2");
    case "psychedelic": return u("streets-v2-dark");
    case "parchment":   return u("outdoor-v2-pastel");
    case "blueprint":   return u("basic-v2-dark");
    case "solar":       return u("streets-v2-pastel");
    case "moss":        return u("outdoor-v2");
    case "frost":       return u("winter-v2");
    default:            return u("topo-v2-dark");
  }
};

