/* ----------------------------------------------------------- Right sidecar */
function RightSidecar({ story, resonant, all, visibleStories, allStories, pending,
  kindFilter, onPickKind, clusterLabels, clusterFilter, onPickCluster,
  colorBy, onPickColor, onClose, onJump, onPreview, ready }) {
  return (
    <aside style={{
      flex: "0 0 340px", width: 340,
      alignSelf: "stretch",
      maxHeight: "calc(100vh - 160px)",
      overflowY: "auto",
      // No background by default — content panels carry their own.
    }}>
      {!ready ? (
        <div style={{ background: T.panel, border: `1px solid ${T.panelEdge}`, borderRadius: T.radius,
          padding: 22, color: T.muted, fontStyle: "italic", textAlign: "center" }}>
          loading the world…
        </div>
      ) : story ? (
        <StoryCard story={story} resonant={resonant} all={all}
          onClose={onClose} onJump={onJump} onPreview={onPreview} />
      ) : (
        <SidecarStats visibleStories={visibleStories} allStories={allStories} pending={pending}
          kindFilter={kindFilter} onPickKind={onPickKind}
          clusterLabels={clusterLabels}
          clusterFilter={clusterFilter} onPickCluster={onPickCluster}
          colorBy={colorBy} onPickColor={onPickColor} />
      )}
    </aside>
  );
}

function SidecarStats({ visibleStories, allStories, pending,
  kindFilter, onPickKind, clusterLabels,
  clusterFilter, onPickCluster, colorBy, onPickColor }) {
  const allClusterLabels = useMemo(() => {
    const m = new Map();
    for (const cl of (clusterLabels?.all || [])) m.set(cl.id, cl.label);
    return m;
  }, [clusterLabels]);
  // Per-kind totals are computed from allStories so the rows keep their count
  // even when filtered out. The big "voices shown" reflects the actual visible total.
  const byKindTotal = useMemo(() => {
    const c = { personal: 0, myth: 0, pareidolia: 0 };
    for (const s of allStories) c[s.kind || "personal"] = (c[s.kind || "personal"] || 0) + 1;
    return c;
  }, [allStories]);

  const toggleKind = (k) => {
    if (!onPickKind) return;
    const next = new Set(kindFilter || new Set(KINDS));
    next.has(k) ? next.delete(k) : next.add(k);
    onPickKind(next);
  };

  const toggleCluster = (id) => {
    if (!onPickCluster) return;
    const next = new Set(clusterFilter || new Set());
    next.has(id) ? next.delete(id) : next.add(id);
    onPickCluster(next);
  };

  const byContinent = useMemo(() => {
    const m = new Map();
    for (const s of visibleStories) {
      const id = continentOf(s.lat, s.lng);
      m.set(id, (m.get(id) || 0) + 1);
    }
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }, [visibleStories]);

  // Use allStories (not visibleStories) for cluster counts so the toggle
  // rows always show, even when their own filter has hidden them.
  const byCluster = useMemo(() => {
    const m = new Map();
    for (const s of allStories) {
      if (!kindFilter || kindFilter.has(s.kind || "personal")) {
        const c = typeof s.cluster_id === "number" ? s.cluster_id : -1;
        m.set(c, (m.get(c) || 0) + 1);
      }
    }
    return [...m.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, [allStories, kindFilter]);

  const total = visibleStories.length;
  const grand = allStories.length;

  const Row = ({ label, count, color }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
      {color && <span style={{ width: 8, height: 8, borderRadius: 999, background: color, flex: "0 0 auto" }} />}
      <span style={{ color: T.muted, fontSize: 13, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
        {label}
      </span>
      <span style={{ color: T.ink, fontSize: 13, fontVariantNumeric: "tabular-nums" }}>{count}</span>
    </div>
  );

  return (
    <div style={{ background: T.panel, border: `1px solid ${T.panelEdge}`, borderRadius: T.radius,
      padding: 22, animation: "rise .3s ease both" }}>
      <div style={{ color: T.accent, fontSize: 12, letterSpacing: ".08em", textTransform: "uppercase",
        marginBottom: 6 }}>
        The atlas right now
      </div>
      <div style={{ fontFamily: T.display, fontSize: 32, lineHeight: 1, color: T.ink, marginBottom: 6 }}>
        {total}
        <span style={{ fontSize: 14, color: T.muted, marginLeft: 8, fontFamily: T.body, fontWeight: 400 }}>
          voices shown
        </span>
      </div>
      {total !== grand && (
        <div style={{ color: T.faint, fontSize: 12, fontStyle: "italic" }}>
          of {grand} total — filtered
        </div>
      )}
      {pending.length > 0 && (
        <div style={{ color: T.sage, fontSize: 12, marginTop: 4 }}>
          {pending.length} awaiting review this session
        </div>
      )}

      <div style={{ marginTop: 18 }}>
        <SectionHeader title="By kind · click to toggle"
          colorByKey="kind" colorBy={colorBy} onPickColor={onPickColor} />
        {[
          { id: "personal",   label: "Personal story",     color: KIND_ACCENT_COLOR.personal },
          { id: "myth",       label: "Myth or tale",       color: "#ffd166" },
          { id: "pareidolia", label: "Nature pareidolia",  color: KIND_ACCENT_COLOR.pareidolia },
        ].map(({ id, label, color }) => {
          const on = kindFilter ? kindFilter.has(id) : true;
          return (
            <button key={id} onClick={() => toggleKind(id)} style={{
              display: "flex", alignItems: "center", gap: 8, width: "100%",
              marginBottom: 4,
              background: "transparent",
              border: "none",
              padding: "6px 0",
              cursor: "pointer",
              fontFamily: T.body,
              textAlign: "left",
            }}>
              <span style={{
                width: 10, height: 10, borderRadius: 999,
                background: on ? color : "transparent",
                border: `1.5px solid ${color}`,
                flex: "0 0 auto",
                opacity: on ? 1 : 0.5,
              }} />
              <span style={{
                color: on ? T.ink : T.faint,
                fontSize: 13, flex: 1,
                overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
                textDecoration: on ? "none" : "line-through",
                textDecorationColor: T.faint,
              }}>{label}</span>
              <span style={{
                color: on ? T.muted : T.faint,
                fontSize: 13, fontVariantNumeric: "tabular-nums",
              }}>{byKindTotal[id] || 0}</span>
            </button>
          );
        })}
      </div>

      {byContinent.length > 0 && (
        <div style={{ marginTop: 18 }}>
          <SectionHeader title="By continent"
            colorByKey="continent" colorBy={colorBy} onPickColor={onPickColor} />
          {byContinent.map(([id, n]) => (
            <Row key={id} label={CONTINENT_LABEL[id] || id} count={n} color={CONTINENT_PALETTE[id]} />
          ))}
        </div>
      )}

      {byCluster.length > 0 && byCluster[0][0] !== -1 && (
        <div style={{ marginTop: 18 }}>
          <SectionHeader title="Semantic clusters · click to toggle"
            colorByKey="cluster" colorBy={colorBy} onPickColor={onPickColor} />
          {byCluster.map(([id, n]) => {
            if (id === -1) return null;
            const anySelected = clusterFilter && clusterFilter.size > 0;
            const on = !anySelected || clusterFilter.has(id);
            const color = CLUSTER_PALETTE[id % CLUSTER_PALETTE.length];
            return (
              <button key={id} onClick={() => toggleCluster(id)} style={{
                display: "flex", alignItems: "center", gap: 8, width: "100%",
                marginBottom: 4,
                background: "transparent",
                border: "none",
                padding: "6px 0",
                cursor: "pointer",
                fontFamily: T.body,
                textAlign: "left",
              }}>
                <span style={{
                  width: 10, height: 10, borderRadius: 999,
                  background: on ? color : "transparent",
                  border: `1.5px solid ${color}`,
                  flex: "0 0 auto",
                  opacity: on ? 1 : 0.5,
                }} />
                <span style={{
                  color: on ? T.ink : T.faint,
                  fontSize: 13, flex: 1,
                  overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
                  textDecoration: on ? "none" : "line-through",
                  textDecorationColor: T.faint,
                }}>{allClusterLabels.get(id) || `Cluster ${id + 1}`}</span>
                <span style={{
                  color: on ? T.muted : T.faint,
                  fontSize: 13, fontVariantNumeric: "tabular-nums",
                }}>{n}</span>
              </button>
            );
          })}
        </div>
      )}

      <div style={{ marginTop: 22, color: T.faint, fontSize: 12, fontStyle: "italic", lineHeight: 1.55 }}>
        Tap any glowing point on the map to read a story. The list of resonant
        siblings will appear here too.
      </div>
    </div>
  );
}

function SectionTitle({ children }) {
  return (
    <div style={{ color: T.muted, fontSize: 11, letterSpacing: ".1em",
      textTransform: "uppercase", marginBottom: 8 }}>{children}</div>
  );
}

/** Section title with an inline "color by" badge that toggles the map's
 *  pin-coloring dimension. Slick: a small chip that lights up when active. */
function SectionHeader({ title, colorByKey, colorBy, onPickColor }) {
  const active = colorBy === colorByKey;
  const canPick = !!onPickColor;
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 8,
      marginBottom: 8,
    }}>
      <div style={{
        color: T.muted, fontSize: 11, letterSpacing: ".1em",
        textTransform: "uppercase", flex: 1,
        overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
      }}>{title}</div>
      {canPick && (
        <button
          onClick={() => onPickColor(colorByKey)}
          title={active ? "Map is colored by this" : "Color the map by this"}
          style={{
            display: "inline-flex", alignItems: "center", gap: 5,
            padding: "2px 8px",
            borderRadius: 999,
            background: active ? T.accent : "transparent",
            border: `1px solid ${active ? T.accent : T.fieldEdge}`,
            color: active ? T.bg : T.faint,
            fontFamily: T.body, fontSize: 10,
            letterSpacing: ".08em", textTransform: "uppercase",
            cursor: "pointer",
            transition: "background .15s ease, color .15s ease, border-color .15s ease",
            flex: "0 0 auto",
          }}
        >
          <span style={{ fontSize: 9, lineHeight: 1 }}>{active ? "●" : "○"}</span>
          {active ? "coloring" : "color by"}
        </button>
      )}
    </div>
  );
}

/* ----------------------------------------------------------- Story card */

// Friendly label lookup for environment & altered-state ids.
const ENV_LABEL_BY_ID = Object.fromEntries(
  [...ENVIRONMENT_ELEMENTS, ...ENVIRONMENT_BIOMES].map((e) => [e.id, e.label])
);
const SENSATION_LABEL_BY_ID = Object.fromEntries(SENSATIONS.map((s) => [s.id, s.label]));
const ALTERED_LABEL_BY_ID = Object.fromEntries(ALTERED_STATES.map((s) => [s.id, s.label]));

function StoryCard({ story, resonant, all, onClose, onJump, onPreview }) {
  const [expanded, setExpanded] = useState(null);   // id of currently-expanded resonance row
  const [previewData, setPreviewData] = useState({}); // id → fetched detail

  useEffect(() => { setExpanded(null); }, [story?.id]); // reset when the main story changes

  // Lazily fetch the full detail for an expanded resonance row.
  useEffect(() => {
    if (!expanded || previewData[expanded]) return;
    let cancelled = false;
    fetch(api(`/api/stories/${encodeURIComponent(expanded)}`))
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => { if (!cancelled && j) setPreviewData((p) => ({ ...p, [expanded]: j })); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [expanded, previewData]);

  // Tell the map which pin (if any) is being previewed so it can highlight it.
  useEffect(() => {
    if (onPreview) onPreview(expanded);
  }, [expanded, onPreview]);

  // Resonance comes from the API (text-embedding KNN). Fall back to the old
  // keyword/category overlap when the resonance call hasn't returned yet, so
  // the section never goes empty mid-fetch.
  let related = Array.isArray(resonant) ? resonant : [];
  if (related.length === 0) {
    const subj = (story.connection_subject || "").toLowerCase();
    const types = new Set(story.connection_types || []);
    related = (all || []).filter((s) => s.id !== story.id && (
      (subj && (s.connection_subject || "").toLowerCase() === subj) ||
      (s.connection_types || []).some((t) => types.has(t))
    )).slice(0, 4);
  }

  const kindCfg = kindOf(story.kind);
  const text = story.text || story.snippet || "";

  // Personal-only enrichments.
  const env = Array.isArray(story.environment) ? story.environment : [];
  const altered = story.altered_state && story.altered_state !== "ordinary"
    ? story.altered_state : null;
  const body = Array.isArray(story.body) ? story.body : [];

  return (
    <div style={{ marginTop: 18, background: T.panel, border: `1px solid ${T.panelEdge}`,
      borderRadius: T.radius, padding: 22, animation: "rise .3s ease both" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", gap: 12 }}>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 6,
            color: T.accent, fontSize: 13, letterSpacing: ".06em", textTransform: "uppercase" }}>
            <span style={{ fontSize: 16, lineHeight: 1 }}>{kindCfg.sigil}</span>
            {kindCfg.label}
          </span>
          {(story.connection_types || []).map((t) => <Tag key={t}>{t}</Tag>)}
          {story.connection_subject && <Tag accent>{story.connection_subject}</Tag>}
          {story.source === "voice" && (
            <Tag>{story.voice_visibility === "public" ? "🔊 voice" : "voice · transcript only"}</Tag>
          )}
        </div>
        <button onClick={onClose} style={{ ...ghostBtn, padding: "4px 10px" }}>✕</button>
      </div>

      {story.image_url && (
        <a href={api(story.image_url)} target="_blank" rel="noopener noreferrer"
          style={{ display: "block", marginTop: 14, borderRadius: 12, overflow: "hidden",
            border: `1px solid ${T.panelEdge}`, maxHeight: 360, background: T.bg }}>
          <img src={api(story.image_url)} alt="pareidolia photograph"
            style={{ display: "block", width: "100%", maxHeight: 360, objectFit: "contain" }} />
        </a>
      )}

      <p style={{ fontFamily: T.display, fontSize: 21, lineHeight: 1.4, margin: "16px 0 8px", fontWeight: 500 }}>
        “{text}”
      </p>
      {story.text_long && <p style={{ color: T.muted, fontSize: 15, lineHeight: 1.6 }}>{story.text_long}</p>}

      {story.source === "voice" && story.voice_visibility === "public" && (story.audio_url || story._audioUrl) && (
        <audio controls
          src={story.audio_url ? api(story.audio_url) : story._audioUrl}
          style={{ width: "100%", marginTop: 10 }} />
      )}

      {(env.length > 0 || altered || body.length > 0) && (
        <div style={{ marginTop: 16, display: "grid", gap: 10 }}>
          {env.length > 0 && (
            <CardRow label="In">
              {env.map((id) => <Tag key={id}>{ENV_LABEL_BY_ID[id] || id}</Tag>)}
            </CardRow>
          )}
          {altered && (
            <CardRow label="State">
              <Tag accent>
                {ALTERED_LABEL_BY_ID[altered] || altered}
                {story.altered_state_detail ? ` · ${story.altered_state_detail}` : ""}
              </Tag>
            </CardRow>
          )}
          {body.length > 0 && (
            <CardRow label="Felt in">
              {body.map((m) => {
                const region = BODY_REGION_BY_ID[m.region];
                const ids = Array.isArray(m.sensations) ? m.sensations
                          : (m.sensation ? [m.sensation] : []);
                const labels = ids.map((id) =>
                  id === "custom" ? (m.custom || "(custom)")
                  : (SENSATION_LABEL_BY_ID[id] || id));
                return (
                  <Tag key={m.region}>
                    <strong>{region?.label || m.region}</strong>
                    <span style={{ color: T.muted }}> · {labels.join(", ")}</span>
                  </Tag>
                );
              })}
            </CardRow>
          )}
        </div>
      )}

      <div style={{ color: T.faint, fontSize: 13, marginTop: 12 }}>
        {[story.age_band, story.gender].filter(Boolean).join(" · ") || "anonymous"}
      </div>

      {related.length > 0 && (
        <div style={{ marginTop: 18, borderTop: `1px solid ${T.panelEdge}`, paddingTop: 14 }}>
          <div style={{ color: T.accent, fontSize: 12, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 10 }}>
            Resonates with
          </div>
          <div style={{ display: "grid", gap: 8 }}>
            {related.map((s) => {
              const label = s.connection_subject || (s.connection_types || [])[0] || kindOf(s.kind).label;
              const snippet = (s.snippet || s.text || "").trim();
              const isExpanded = expanded === s.id;
              const detail = previewData[s.id];
              const fullText = detail?.text || s.text || snippet;
              const longText = detail?.text_long;
              return (
                <div key={s.id} style={{ ...relRow, display: "block", padding: 0, overflow: "hidden" }}>
                  <button
                    onClick={() => setExpanded(isExpanded ? null : s.id)}
                    style={{
                      width: "100%", border: "none", background: "transparent",
                      padding: "10px 12px", textAlign: "left",
                      display: "flex", flexDirection: "column", gap: 4,
                      cursor: "pointer", fontFamily: T.body,
                    }}>
                    <span style={{ color: T.accent, fontSize: 13 }}>
                      ◦ {label}
                      {typeof s.score === "number" && (
                        <span style={{ color: T.faint, marginLeft: 6 }}>
                          {Math.round(s.score * 100)}%
                        </span>
                      )}
                    </span>
                    <span style={{ color: T.muted, fontSize: 13, textAlign: "left" }}>
                      {isExpanded
                        ? fullText
                        : `${snippet.slice(0, 80)}${snippet.length > 80 ? "…" : ""}`}
                    </span>
                  </button>
                  {isExpanded && (
                    <div style={{
                      padding: "0 12px 12px", color: T.muted, fontSize: 13, lineHeight: 1.55,
                      borderTop: `1px solid ${T.fieldEdge}`, marginTop: 2, paddingTop: 10,
                      animation: "rise .22s ease both",
                    }}>
                      {longText && (
                        <div style={{ color: T.faint, fontStyle: "italic", marginBottom: 8 }}>
                          {longText}
                        </div>
                      )}
                      <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
                        <span style={{ color: T.faint, fontSize: 12 }}>
                          {kindOf(detail?.kind || s.kind).label}
                          {detail?.location_label ? ` · ${detail.location_label}` : ""}
                        </span>
                        <button onClick={() => onJump(s.id)}
                          style={{ marginLeft: "auto", background: "transparent",
                            border: `1px solid ${T.fieldEdge}`, color: T.accent,
                            borderRadius: 999, padding: "4px 12px", cursor: "pointer",
                            fontSize: 12, fontFamily: T.body }}>
                          Open this story →
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

/* ----------------------------------------------------------- Contribute flow */
// Step id → label for the breadcrumb. Each KIND_CONFIG[k].steps lists which
// ids to run in which order.
const STEP_META = {
  locate:  { label: "Locate",          component: (p) => <StepLocate  {...p} /> },
  about:   { label: "About you",       component: (p) => <StepAbout   {...p} /> },
  story:   { label: "Your story",      component: (p) => <StepStory   {...p} /> },
  pheno:   { label: "The experience",  component: (p) => <StepPheno   {...p} /> },
  body:    { label: "Body sensations", component: (p) => <StepBody    {...p} /> },
  more:    { label: "Say more",        component: (p) => <StepMore    {...p} /> },
  consent: { label: "Consent",         component: (p) => <StepConsent {...p} /> },
};

function ContributeFlow({ draft, setDraft, onClose, onSubmit, onStep }) {
  const [step, setStepRaw] = useState(0);
  const setStep = (next) => {
    setStepRaw(next);
    if (onStep) onStep(typeof next === "function" ? next(step) : next);
  };
  useEffect(() => { if (onStep) onStep(0); }, []);            // initial sync
  const up = (patch) => setDraft((d) => ({ ...d, ...patch }));

  const k = kindOf(draft.kind);
  const stepIds = k.steps;
  const currentId = stepIds[step];
  const isLast = step === stepIds.length - 1;

  const canNext = () => {
    if (currentId === "locate")  return draft.lat != null;
    if (currentId === "story")   return (draft.text || "").trim().length > 2;
    if (currentId === "consent") return !!draft.consent;
    return true;
  };

  const locating = currentId === "locate";
  return (
    <div
      style={locating
        ? { position: "fixed", inset: 0, pointerEvents: "none", zIndex: 50 }
        : overlay}
      onClick={locating ? undefined : onClose}
    >
      <div
        style={locating
          ? { position: "absolute", top: 90, right: 18, width: 340, maxWidth: "calc(100vw - 36px)",
              background: T.panel, border: `1px solid ${T.panelEdge}`, borderRadius: T.radius,
              padding: "16px 18px 18px", boxShadow: "0 24px 60px rgba(0,0,0,0.5)",
              pointerEvents: "auto", animation: "rise .28s ease both" }
          : { ...sheet, pointerEvents: "auto" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <div style={{ display: "flex", gap: 6 }}>
            {stepIds.map((_, i) => (
              <div key={i} style={{ width: 22, height: 3, borderRadius: 2,
                background: i <= step ? T.accent : T.fieldEdge }} />
            ))}
          </div>
          <button onClick={onClose} style={{ ...ghostBtn, padding: "4px 10px" }}>✕</button>
        </div>
        <div style={{ color: T.muted, fontSize: 12, letterSpacing: ".08em", textTransform: "uppercase" }}>
          <span style={{ color: T.accent }}>{k.label}</span>
          {" · "}Step {step + 1} · {STEP_META[currentId].label}
        </div>

        <div style={{ minHeight: 240, marginTop: 14 }}>
          {STEP_META[currentId].component({ draft, up })}
        </div>

        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 18 }}>
          <button onClick={() => (step === 0 ? onClose() : setStep(step - 1))} style={ghostBtn}>
            {step === 0 ? "Cancel" : "Back"}
          </button>
          {!isLast ? (
            <button disabled={!canNext()} onClick={() => setStep(step + 1)}
              style={{ ...primaryBtn, opacity: canNext() ? 1 : 0.4, cursor: canNext() ? "pointer" : "not-allowed" }}>
              Continue
            </button>
          ) : (
            <button disabled={!canNext()} onClick={onSubmit}
              style={{ ...primaryBtn, opacity: canNext() ? 1 : 0.4, cursor: canNext() ? "pointer" : "not-allowed" }}>
              Add to the map
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function StepLocate({ draft, up }) {
  const k = kindOf(draft.kind);
  return (
    <div>
      <Hd>{k.locatePrompt}</Hd>
      <P>{k.locateHelp}</P>
      <div style={{ marginTop: 16, padding: 16, background: T.field, borderRadius: 10, border: `1px solid ${T.fieldEdge}` }}>
        {draft.lat == null
          ? <span style={{ color: T.muted }}>No location yet — tap the map.</span>
          : <span style={{ color: T.sage }}>Pinned at {draft.lat}, {draft.lng} ✓</span>}
      </div>
      <input placeholder="Name this place (optional)" value={draft.location_label}
        onChange={(e) => up({ location_label: e.target.value })} style={input} />
    </div>
  );
}

function StepAbout({ draft, up }) {
  const k = kindOf(draft.kind);
  const showEnvSub =
    draft.kind === "personal" && (draft.connection_types || []).includes("environment");
  return (
    <div>
      <Hd>A few quick things</Hd>
      <Label>Age</Label>
      <Chips options={AGE_BANDS} value={draft.age_band} onChange={(v) => up({ age_band: v })} />
      <Label>Gender</Label>
      <Chips options={GENDERS} value={draft.gender} onChange={(v) => up({ gender: v })} />
      <Label>{k.connectionLabel}</Label>
      <Chips multi
        options={k.connectionOptions.map((c) => c.id)}
        labels={k.connectionOptions.map((c) => c.label)}
        value={draft.connection_types}
        onChange={(v) => up({ connection_types: v })} />

      {showEnvSub && (
        <div style={{ marginTop: 12, padding: 14, background: T.field,
          border: `1px solid ${T.fieldEdge}`, borderRadius: 10 }}>
          <Label>Which element?</Label>
          <Chips multi
            options={ENVIRONMENT_ELEMENTS.map((e) => e.id)}
            labels={ENVIRONMENT_ELEMENTS.map((e) => e.label)}
            iconFor={(id) => <EnvIcon id={id} />}
            value={draft.environment || []}
            onChange={(v) => up({ environment: v })} />
          <Label>Which environment?</Label>
          <Chips multi
            options={ENVIRONMENT_BIOMES.map((e) => e.id)}
            labels={ENVIRONMENT_BIOMES.map((e) => e.label)}
            iconFor={(id) => <EnvIcon id={id} />}
            value={draft.environment || []}
            onChange={(v) => up({ environment: v })} />
        </div>
      )}

      <Label>{k.subjectLabel}</Label>
      <input placeholder={k.subjectPlaceholder} value={draft.connection_subject}
        onChange={(e) => up({ connection_subject: e.target.value })} style={input} />
    </div>
  );
}

function StepStory({ draft, up }) {
  const k = kindOf(draft.kind);
  return (
    <div>
      <Hd>{k.storyHeading}</Hd>
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <Toggle active={draft.mode === "typed"} onClick={() => up({ mode: "typed" })}>✎ Write</Toggle>
        <Toggle active={draft.mode === "voice"} onClick={() => up({ mode: "voice" })}>🎙 Speak</Toggle>
      </div>
      {draft.mode === "voice" && <VoiceRecorder draft={draft} up={up} />}
      <textarea rows={5} value={draft.text} onChange={(e) => up({ text: e.target.value })}
        placeholder={draft.mode === "voice" ? k.storyVoicePlaceholder : k.storyTypedPlaceholder}
        style={{ ...input, resize: "vertical", lineHeight: 1.5 }} />
      {draft.mode === "voice" && (
        <div style={{ marginTop: 6 }}>
          <Label>Who can hear your voice?</Label>
          <Chips options={["transcript_only", "public"]}
            labels={["Keep voice private — show text only", "Let others play my recording"]}
            value={draft.voice_visibility} onChange={(v) => up({ voice_visibility: v })} stack />
        </div>
      )}

      {draft.kind === "pareidolia" && <ImagePicker draft={draft} up={up} />}
    </div>
  );
}

function ImagePicker({ draft, up }) {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState(null);
  const fileRef = useRef(null);

  const onPick = async (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    setError(null);
    if (file.size > 5 * 1024 * 1024) { setError("Image too large (max 5MB)."); return; }
    if (!/^image\/(jpeg|png|webp|gif)$/.test(file.type)) {
      setError("Image must be JPEG, PNG, WebP, or GIF."); return;
    }
    // Optimistic local preview while we upload.
    const localUrl = URL.createObjectURL(file);
    up({ image_local_url: localUrl, image_mime: file.type });
    setUploading(true);
    try {
      const r = await fetch(api("/api/images"), {
        method: "POST",
        headers: { "Content-Type": file.type },
        body: file,
      });
      if (!r.ok) {
        const j = await r.json().catch(() => ({}));
        throw new Error(j.error || `HTTP ${r.status}`);
      }
      const { key, mime } = await r.json();
      up({ image_key: key, image_mime: mime });
    } catch (err) {
      console.warn("[atn] image upload failed", err);
      setError(`Upload failed: ${err.message}`);
      up({ image_key: null, image_local_url: null, image_mime: null });
    } finally {
      setUploading(false);
    }
  };

  const clear = () => {
    if (draft.image_local_url) URL.revokeObjectURL(draft.image_local_url);
    up({ image_key: null, image_local_url: null, image_mime: null });
    if (fileRef.current) fileRef.current.value = "";
  };

  const hasImage = !!(draft.image_local_url || draft.image_key);

  return (
    <div style={{ marginTop: 14 }}>
      <Label>Got a photo of what you saw? (optional)</Label>
      <div style={{ display: "flex", gap: 12, alignItems: "flex-start", flexWrap: "wrap",
        padding: 12, background: T.field, border: `1px solid ${T.fieldEdge}`, borderRadius: 10 }}>
        {hasImage && (
          <div style={{ position: "relative", borderRadius: 8, overflow: "hidden",
            border: `1px solid ${T.fieldEdge}`, width: 120, height: 120, background: T.bg }}>
            <img src={draft.image_local_url || api(`/api/images/${draft.image_key}`)}
              alt="your pareidolia"
              style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
            {uploading && (
              <div style={{ position: "absolute", inset: 0, display: "flex",
                alignItems: "center", justifyContent: "center",
                background: "rgba(6,12,10,0.55)", color: T.ink, fontSize: 12, fontStyle: "italic" }}>
                uploading…
              </div>
            )}
          </div>
        )}
        <div style={{ flex: "1 1 220px", display: "flex", flexDirection: "column", gap: 8 }}>
          <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp,image/gif"
            onChange={onPick}
            style={{ color: T.muted, fontSize: 13, fontFamily: T.body }} />
          <div style={{ color: T.faint, fontSize: 12, fontStyle: "italic" }}>
            JPEG, PNG, WebP or GIF · up to 5MB.
          </div>
          {error && <div style={{ color: "#e07a5f", fontSize: 12 }}>{error}</div>}
          {hasImage && !uploading && (
            <button onClick={clear} style={{ ...ghostBtn, alignSelf: "flex-start", color: "#c2553f",
              borderColor: "rgba(194,85,63,0.35)" }}>remove image</button>
          )}
        </div>
      </div>
    </div>
  );
}

function VoiceRecorder({ draft, up }) {
  const [rec, setRec] = useState(null);
  const [recording, setRecording] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
  const [error, setError] = useState(null);
  const chunks = useRef([]);

  // Pick a mime the browser will actually record in. Chrome → webm; Safari → mp4.
  const pickMime = () => {
    const candidates = ["audio/webm", "audio/ogg", "audio/mp4", "audio/mpeg"];
    for (const m of candidates) {
      if (typeof MediaRecorder !== "undefined" && MediaRecorder.isTypeSupported?.(m)) return m;
    }
    return "audio/webm";
  };

  const transcribe = async (blob) => {
    setTranscribing(true);
    setError(null);
    try {
      const r = await fetch(api("/api/transcribe"), {
        method: "POST",
        headers: { "Content-Type": blob.type || "audio/webm" },
        body: blob,
      });
      if (!r.ok) {
        const j = await r.json().catch(() => ({}));
        throw new Error(j.error || `HTTP ${r.status}`);
      }
      const { audio_key, audio_mime, transcript, lang } = await r.json();
      const patch = { audio_key, audio_mime };
      if (lang) patch.lang = lang;
      // Only fill the textarea if the user hasn't typed anything yet.
      if (transcript && !(draft.text || "").trim()) patch.text = transcript;
      up(patch);
    } catch (e) {
      console.warn("[atn] transcribe failed", e);
      setError(`Transcription failed: ${e.message}. You can still type the transcript and submit.`);
    } finally {
      setTranscribing(false);
    }
  };

  const start = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mime = pickMime();
      const mr = new MediaRecorder(stream, { mimeType: mime });
      chunks.current = [];
      mr.ondataavailable = (e) => { if (e.data && e.data.size > 0) chunks.current.push(e.data); };
      mr.onstop = async () => {
        stream.getTracks().forEach((t) => t.stop());
        const blob = new Blob(chunks.current, { type: mime });
        up({ audioUrl: URL.createObjectURL(blob) });
        transcribe(blob);
      };
      mr.start();
      setRec(mr); setRecording(true);
    } catch (e) {
      setError("Microphone unavailable: " + (e?.message || e));
    }
  };
  const stop = () => { if (rec) rec.stop(); setRecording(false); };

  return (
    <div style={{ padding: 14, background: T.field, border: `1px solid ${T.fieldEdge}`, borderRadius: 10, marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <button onClick={recording ? stop : start} disabled={transcribing}
          style={{ ...primaryBtn,
            background: recording ? "#c2553f" : T.accent,
            opacity: transcribing ? 0.5 : 1,
            cursor: transcribing ? "not-allowed" : "pointer" }}>
          {recording ? "■ Stop" : "● Record"}
        </button>
        {draft.audioUrl && <audio controls src={draft.audioUrl} style={{ height: 34 }} />}
        {transcribing && (
          <span style={{ color: T.muted, fontSize: 13, fontStyle: "italic" }}>transcribing…</span>
        )}
      </div>
      {error && <div style={{ color: "#e07a5f", fontSize: 12, marginTop: 8 }}>{error}</div>}
      <div style={{ color: T.faint, fontSize: 12, marginTop: 8, fontStyle: "italic" }}>
        Recording is held locally until you submit; on stop we upload to Whisper and the transcript appears below — edit freely.
      </div>
    </div>
  );
}

function StepPheno({ draft, up }) {
  const k = kindOf(draft.kind);
  const isPersonal = draft.kind === "personal";
  const altered = draft.altered_state || "";
  const showAlteredDetail = altered && altered !== "ordinary" && altered !== "";

  return (
    <div>
      <Hd>{k.phenoHeading}</Hd>
      <P>Move each toward what fits. Placeholder instrument — swap in your validated scales.</P>
      <div style={{ marginTop: 14, display: "grid", gap: 14 }}>
        {k.pheno.map((dim) => (
          <div key={dim.id}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14 }}>
              <span>{dim.label}</span>
              <span style={{ color: T.accent }}>{PHENO_SCALE[draft.pheno[dim.id] || 0]}</span>
            </div>
            <input type="range" min={0} max={4} value={draft.pheno[dim.id] || 0}
              onChange={(e) => up({ pheno: { ...draft.pheno, [dim.id]: +e.target.value } })}
              style={{ width: "100%", accentColor: T.accent }} />
          </div>
        ))}
      </div>

      {isPersonal && (
        <div style={{ marginTop: 22, padding: 14, background: T.field,
          border: `1px solid ${T.fieldEdge}`, borderRadius: 10 }}>
          <Label>Were you in an altered state during the experience?</Label>
          <Chips
            options={ALTERED_STATES.map((s) => s.id)}
            labels={ALTERED_STATES.map((s) => s.label)}
            value={altered}
            onChange={(v) => up({ altered_state: v })} />
          {showAlteredDetail && (
            <input
              placeholder={
                altered === "psychedelic" ? "Which one? (e.g. psilocybin, ayahuasca, LSD)" :
                altered === "meditation"  ? "What kind? (e.g. vipassana, breathwork)" :
                altered === "dream"       ? "Anything to add about the dream?" :
                altered === "ritual"      ? "What ritual or ceremony?" :
                                            "Tell us more (optional)"
              }
              maxLength={200}
              value={draft.altered_state_detail || ""}
              onChange={(e) => up({ altered_state_detail: e.target.value })}
              style={{ ...input, marginTop: 10 }} />
          )}
        </div>
      )}
    </div>
  );
}

function StepBody({ draft, up }) {
  const marks = draft.body || [];
  const markedIds = useMemo(() => new Set(marks.map((m) => m.region)), [marks]);
  const [editing, setEditing] = useState(null);

  const onRegionClick = (rid) => {
    if (editing === rid) { setEditing(null); return; }
    if (markedIds.has(rid)) { setEditing(rid); return; }
    if (marks.length >= MAX_BODY_MARKS) return;
    setEditing(rid);
  };

  // Toggle a sensation on/off for the given region; the mark stays open so
  // the user can keep adding qualities until they press Done.
  const toggleSensation = (rid, sensation) => {
    const existing = marks.find((m) => m.region === rid);
    const current = (existing?.sensations || []).slice();
    const idx = current.indexOf(sensation);
    if (idx >= 0) current.splice(idx, 1);
    else if (current.length < 8) current.push(sensation);
    const next = marks.filter((m) => m.region !== rid);
    if (current.length > 0) {
      next.push({ region: rid, sensations: current, ...(existing?.custom ? { custom: existing.custom } : {}) });
    }
    up({ body: next });
  };
  const setCustomForRegion = (rid, customText) => {
    const existing = marks.find((m) => m.region === rid);
    const sens = (existing?.sensations || []).slice();
    if (!sens.includes("custom")) sens.push("custom");
    const next = marks.filter((m) => m.region !== rid);
    next.push({ region: rid, sensations: sens, custom: customText });
    up({ body: next });
  };
  const removeMark = (rid) => {
    up({ body: marks.filter((m) => m.region !== rid) });
    setEditing(null);
  };

  const editingRegion = editing ? BODY_REGION_BY_ID[editing] : null;
  const editingCurrent = editing ? marks.find((m) => m.region === editing) : null;

  return (
    <div>
      <Hd>Where in the body?</Hd>
      <P>
        Click up to <strong>{MAX_BODY_MARKS} places</strong> on the body where you felt the connection,
        then pick what the sensation was like. You can also write your own word if none of the eight fit.
      </P>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start", flexWrap: "wrap", marginTop: 6 }}>
        <BodySilhouette marks={marks} editing={editing} onRegionClick={onRegionClick} />
        <div style={{ flex: "1 1 220px", minWidth: 220 }}>
          {editingRegion ? (
            <SensationGrid
              region={editingRegion}
              current={editingCurrent}
              onToggle={(s) => toggleSensation(editingRegion.id, s)}
              onCustom={(text) => setCustomForRegion(editingRegion.id, text)}
              onRemove={() => removeMark(editingRegion.id)}
              onDone={() => setEditing(null)}
            />
          ) : (
            <MarksSummary marks={marks} onEdit={(rid) => setEditing(rid)} />
          )}
        </div>
      </div>
    </div>
  );
}

function BodySilhouette({ marks, editing, onRegionClick }) {
  const markedIds = new Set(marks.map((m) => m.region));
  const [hovered, setHovered] = useState(null);
  const hoveredLabel = hovered ? BODY_REGION_BY_ID[hovered]?.label : null;

  // Unified silhouette: every region shares the same neutral fill + no stroke
  // so the body reads as one figure. Highlight comes from hover/marked/editing
  // state via an overlay shape with the same geometry on top.
  const BODY = "rgba(143,184,154,0.16)";

  const overlayFor = (rid) => {
    if (editing === rid)       return { fill: T.accent,              stroke: T.accent, opacity: 0.85 };
    if (markedIds.has(rid))    return { fill: "rgba(230,169,78,0.55)", stroke: T.accent, opacity: 1 };
    if (hovered === rid)       return { fill: "rgba(143,184,154,0.30)", stroke: T.sage,  opacity: 1 };
    return null;
  };

  const shapeEl = (s, i, fill, stroke, strokeWidth = 0, hitTarget = false) => {
    const common = { fill, stroke, strokeWidth, pointerEvents: hitTarget ? "all" : "none" };
    return s.kind === "ellipse"
      ? <ellipse key={i} cx={s.cx} cy={s.cy} rx={s.rx} ry={s.ry} {...common} />
      : <rect    key={i} x={s.x}  y={s.y}  width={s.w}  height={s.h}  rx={s.r}  {...common} />;
  };

  return (
    <div style={{ width: "100%", maxWidth: 260, flex: "0 0 260px", display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{
        minHeight: 22, fontSize: 13, fontFamily: T.body, color: T.muted,
        textAlign: "center", marginBottom: 4,
      }}>
        {hoveredLabel
          ? <span style={{ color: T.ink }}>{hoveredLabel}</span>
          : <span style={{ fontStyle: "italic" }}>Hover or tap a part of the body</span>}
      </div>
      <svg viewBox="0 0 100 200" style={{ display: "block", width: "100%" }}>
        {/* Layer 1: the unified body silhouette — no strokes, all same fill,
            no pointer events so hover state lives on layer 2 only. */}
        <g fill={BODY} pointerEvents="none">
          {BODY_REGIONS.map((r) =>
            r.shapes.map((s, i) => shapeEl(s, `${r.id}-bg-${i}`, BODY, "none"))
          )}
        </g>

        {/* Layer 2: per-region hit + highlight. Transparent by default, painted
            only when hovered / marked / editing. pointer-events:"all" ensures
            transparent shapes still capture clicks/hover. */}
        {BODY_REGIONS.map((r) => {
          const o = overlayFor(r.id);
          return (
            <g key={r.id}
               onMouseEnter={() => setHovered(r.id)}
               onMouseLeave={() => setHovered((h) => (h === r.id ? null : h))}
               onClick={() => onRegionClick(r.id)}
               style={{ cursor: "pointer" }}>
              <title>{r.label}</title>
              {r.shapes.map((s, i) => shapeEl(
                s, i,
                o ? o.fill : "transparent",
                o ? o.stroke : "transparent",
                o ? 0.8 : 0,
                true   // always a hit target
              ))}
            </g>
          );
        })}

        {/* Center markers on marked regions */}
        {marks.map((m) => {
          const r = BODY_REGION_BY_ID[m.region]; if (!r) return null;
          return r.shapes.map((s, i) => {
            const cx = s.kind === "ellipse" ? s.cx : s.x + s.w / 2;
            const cy = s.kind === "ellipse" ? s.cy : s.y + s.h / 2;
            return (
              <g key={`${m.region}-dot-${i}`} pointerEvents="none">
                <circle cx={cx} cy={cy} r={2.2} fill={T.bg} />
                <circle cx={cx} cy={cy} r={1.4} fill={T.accent} />
              </g>
            );
          });
        })}
      </svg>
    </div>
  );
}

function SensationGrid({ region, current, onToggle, onCustom, onRemove, onDone }) {
  const activeSet = useMemo(() => new Set(current?.sensations || []), [current]);
  const [customMode, setCustomMode] = useState(activeSet.has("custom"));
  const [customText, setCustomText] = useState(current?.custom || "");

  // Every cell — sensation buttons, "other…", and the inline custom input —
  // shares this style so the grid reads as one tight 3×3 block.
  const cellBase = {
    height: 56,
    borderRadius: 10,
    fontSize: 13,
    fontFamily: T.body,
    border: `1px solid ${T.fieldEdge}`,
    background: T.bg,
    color: T.ink,
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    textAlign: "center",
    padding: "0 6px",
    boxSizing: "border-box",
    transition: "background 120ms ease, border-color 120ms ease",
  };
  const cellActive = {
    background: T.accent,
    color: "#231603",
    fontWeight: 600,
    border: `1px solid ${T.accent}`,
  };

  return (
    <div style={{ padding: 14, background: T.field, border: `1px solid ${T.fieldEdge}`, borderRadius: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <span style={{ fontWeight: 600, fontFamily: T.display }}>
          {region.label}
          <span style={{ color: T.muted, fontWeight: 400, fontSize: 12 }}> · what did it feel like? (multi-pick)</span>
        </span>
        <button onClick={onDone}
          style={{ background: "transparent", border: "none", color: T.muted, cursor: "pointer", fontSize: 14 }}>
          ✕
        </button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 6 }}>
        {SENSATIONS.map((s) => {
          const active = activeSet.has(s.id);
          return (
            <button key={s.id} onClick={() => onToggle(s.id)}
              style={{ ...cellBase, ...(active ? cellActive : null) }}>
              {s.label}
            </button>
          );
        })}

        {customMode ? (
          <input autoFocus value={customText} maxLength={40}
            onChange={(e) => setCustomText(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && customText.trim()) { onCustom(customText.trim()); setCustomMode(false); } }}
            placeholder="other…"
            style={{
              ...cellBase,
              cursor: "text",
              border: `1px solid ${T.accent}`,
              outline: "none",
              minWidth: 0, width: "100%",
            }} />
        ) : (
          <button onClick={() => setCustomMode(true)}
            style={{ ...cellBase, color: T.muted, fontStyle: "italic" }}>
            {activeSet.has("custom") && current?.custom ? current.custom : "other…"}
          </button>
        )}
      </div>

      {customMode && (
        <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 12, gap: 8 }}>
          <button onClick={() => setCustomMode(false)} style={ghostBtn}>cancel</button>
          <button
            onClick={() => { onCustom(customText.trim()); setCustomMode(false); }}
            disabled={!customText.trim()}
            style={{ ...primaryBtn, opacity: customText.trim() ? 1 : 0.4 }}>add</button>
        </div>
      )}

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center",
        marginTop: 12, gap: 8 }}>
        {current ? (
          <button onClick={onRemove}
            style={{ ...ghostBtn, color: "#c2553f", borderColor: "rgba(194,85,63,0.35)" }}>
            remove this mark
          </button>
        ) : <span />}
        <button onClick={onDone} style={primaryBtn}>Done</button>
      </div>
    </div>
  );
}

function MarksSummary({ marks, onEdit }) {
  if (marks.length === 0) {
    return (
      <div style={{ color: T.muted, fontSize: 13, fontStyle: "italic",
        padding: 14, background: T.field, border: `1px dashed ${T.fieldEdge}`, borderRadius: 10 }}>
        Click a part of the body on the left to begin. You can mark up to {MAX_BODY_MARKS} places.
      </div>
    );
  }
  return (
    <div style={{ display: "grid", gap: 6 }}>
      <div style={{ color: T.muted, fontSize: 12, letterSpacing: ".08em",
        textTransform: "uppercase" }}>Your marks · {marks.length} / {MAX_BODY_MARKS}</div>
      {marks.map((m) => {
        const r = BODY_REGION_BY_ID[m.region];
        const ids = Array.isArray(m.sensations) ? m.sensations
                   : (m.sensation ? [m.sensation] : []);
        const labels = ids.map((id) =>
          id === "custom" ? (m.custom || "(custom)")
          : (SENSATIONS.find((s) => s.id === id)?.label ?? id));
        return (
          <button key={m.region} onClick={() => onEdit(m.region)} style={{
            display: "flex", justifyContent: "space-between", alignItems: "center",
            padding: "10px 12px", background: T.field, border: `1px solid ${T.fieldEdge}`,
            borderRadius: 10, color: T.ink, fontFamily: T.body, cursor: "pointer", fontSize: 14,
          }}>
            <span><strong>{r?.label}</strong> <span style={{ color: T.muted }}>· {labels.join(", ")}</span></span>
            <span style={{ color: T.faint, fontSize: 12 }}>edit</span>
          </button>
        );
      })}
      {marks.length < MAX_BODY_MARKS && (
        <div style={{ color: T.faint, fontSize: 12, fontStyle: "italic", marginTop: 2 }}>
          Click another part of the body to add one more.
        </div>
      )}
    </div>
  );
}

function StepMore({ draft, up }) {
  const k = kindOf(draft.kind);
  return (
    <div>
      <Hd>{k.moreHeading}</Hd>
      <P>{k.morePrompt} Skip freely.</P>
      <textarea rows={6} value={draft.text_long} onChange={(e) => up({ text_long: e.target.value })}
        placeholder="A longer reflection, the fuller story, the part that's hard to compress…"
        style={{ ...input, resize: "vertical", lineHeight: 1.5 }} />
    </div>
  );
}

function StepConsent({ draft, up }) {
  return (
    <div>
      <Hd>One last thing</Hd>
      <P>Your story will appear on a public map and be used, anonymously, for research into how people relate to nature. You can ask for it to be removed at any time.</P>
      <label style={{ display: "flex", gap: 12, alignItems: "flex-start", marginTop: 18, cursor: "pointer",
        padding: 14, background: T.field, border: `1px solid ${draft.consent ? T.accent : T.fieldEdge}`, borderRadius: 10 }}>
        <input type="checkbox" checked={draft.consent} onChange={(e) => up({ consent: e.target.checked })}
          style={{ marginTop: 3, accentColor: T.accent, width: 18, height: 18 }} />
        <span style={{ fontSize: 14, color: T.ink }}>
          I consent to my anonymised story{draft.mode === "voice" && draft.voice_visibility === "public" ? " and voice recording" : ""} being shared publicly and used for research.
        </span>
      </label>
    </div>
  );
}

/* ----------------------------------------------------------- Small UI pieces */
const Hd = ({ children }) => <div style={{ fontFamily: T.display, fontSize: 22, fontWeight: 600, marginBottom: 6 }}>{children}</div>;
const P = ({ children }) => <p style={{ color: T.muted, fontSize: 15, lineHeight: 1.6, margin: 0 }}>{children}</p>;
const Label = ({ children }) => <div style={{ fontSize: 12, color: T.faint, letterSpacing: ".07em", textTransform: "uppercase", margin: "18px 0 8px" }}>{children}</div>;

function Tag({ children, accent }) {
  return <span style={{ fontSize: 12, padding: "4px 10px", borderRadius: 999,
    background: accent ? T.accentSoft : T.field, color: accent ? T.accent : T.muted,
    border: `1px solid ${accent ? "transparent" : T.fieldEdge}` }}>{children}</span>;
}

function CardRow({ label, children }) {
  return (
    <div style={{ display: "flex", gap: 10, alignItems: "baseline", flexWrap: "wrap" }}>
      <span style={{ color: T.faint, fontSize: 11, letterSpacing: ".08em",
        textTransform: "uppercase", minWidth: 56 }}>{label}</span>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>{children}</div>
    </div>
  );
}

function Chips({ options, labels, iconFor, value, onChange, multi, stack }) {
  const isOn = (o) => (multi ? (value || []).includes(o) : value === o);
  const toggle = (o) => {
    if (!multi) return onChange(o);
    const v = new Set(value || []); v.has(o) ? v.delete(o) : v.add(o);
    onChange([...v]);
  };
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, flexDirection: stack ? "column" : "row" }}>
      {options.map((o, i) => {
        const on = isOn(o);
        const icon = iconFor ? iconFor(o) : null;
        return (
          <button key={o} onClick={() => toggle(o)} style={{
            display: "inline-flex", alignItems: "center", gap: icon ? 8 : 0,
            padding: "8px 14px", borderRadius: 999, fontSize: 14, fontFamily: T.body, textAlign: "left",
            background: on ? T.accent : T.field, color: on ? "#231603" : T.ink,
            border: `1px solid ${on ? "transparent" : T.fieldEdge}`, cursor: "pointer",
            fontWeight: on ? 600 : 400,
          }}>
            {icon && <span style={{ display: "inline-flex", opacity: on ? 0.85 : 0.7 }}>{icon}</span>}
            {labels ? labels[i] : o}
          </button>
        );
      })}
    </div>
  );
}

function Toggle({ active, onClick, children }) {
  return <button onClick={onClick} style={{ flex: 1, padding: "10px", borderRadius: 10, fontSize: 14, fontFamily: T.body,
    background: active ? T.accent : T.field, color: active ? "#231603" : T.ink, fontWeight: active ? 600 : 400,
    border: `1px solid ${active ? "transparent" : T.fieldEdge}`, cursor: "pointer" }}>{children}</button>;
}

const primaryBtn = { background: T.accent, color: "#231603", border: "none", borderRadius: 10,
  padding: "10px 18px", fontSize: 14, fontWeight: 600, fontFamily: T.body, cursor: "pointer" };
const ghostBtn = { background: "transparent", color: T.muted, border: `1px solid ${T.fieldEdge}`,
  borderRadius: 10, padding: "9px 16px", fontSize: 14, fontFamily: T.body, cursor: "pointer" };
const input = { width: "100%", marginTop: 10, background: T.field, color: T.ink, fontFamily: T.body, fontSize: 15,
  border: `1px solid ${T.fieldEdge}`, borderRadius: 10, padding: "11px 13px", boxSizing: "border-box", outline: "none" };
const relRow = { display: "flex", gap: 10, alignItems: "baseline", background: T.field, border: `1px solid ${T.fieldEdge}`,
  borderRadius: 8, padding: "9px 12px", cursor: "pointer", textAlign: "left", width: "100%", fontFamily: T.body };
const overlay = { position: "fixed", inset: 0, background: "rgba(6,12,10,0.62)", backdropFilter: "blur(3px)",
  display: "flex", alignItems: "flex-end", justifyContent: "center", zIndex: 50, animation: "fade .2s ease both" };
const sheet = { background: T.bg, border: `1px solid ${T.panelEdge}`, borderRadius: "18px 18px 0 0",
  width: "100%", maxWidth: 560, padding: "20px 20px 26px", maxHeight: "92vh", overflowY: "auto",
  boxShadow: "0 -20px 60px rgba(0,0,0,0.5)", animation: "rise .28s ease both" };

function FontAndKeyframes() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Spectral:wght@300;400;500&display=swap');
      * { box-sizing: border-box; }
      body { margin: 0; background: var(--atn-bg); color: var(--atn-ink); }
      @keyframes fade { from { opacity: 0 } to { opacity: 1 } }
      @keyframes rise { from { opacity: 0; transform: translateY(14px) } to { opacity: 1; transform: none } }
      .pulse { animation: pulse 2.4s ease-in-out infinite; }
      @keyframes pulse { 0%,100% { opacity: .7 } 50% { opacity: 1 } }
      .ring { animation: ring 2s ease-out infinite; }
      @keyframes ring { 0% { r: 7; opacity: .6 } 100% { r: 16; opacity: 0 } }

      /* Preview rings — wrap a pin to lock visual attention without changing selection. */
      .preview-ring-outer { animation: previewRingOut 1.6s ease-in-out infinite; }
      .preview-ring-inner { animation: previewRingIn  1.6s ease-in-out infinite; }
      @keyframes previewRingOut {
        0%   { transform: scale(0.85); opacity: 0.95 }
        70%  { transform: scale(1.6);  opacity: 0    }
        100% { transform: scale(1.6);  opacity: 0    }
      }
      @keyframes previewRingIn {
        0%, 100% { transform: scale(1);    opacity: 0.55 }
        50%      { transform: scale(1.15); opacity: 0.9  }
      }
      .thread { animation: dash 14s linear infinite; }
      @keyframes dash { to { stroke-dashoffset: -120 } }

      /* drifting graticule (aurora theme) */
      .graticule.drift { stroke-dasharray: 1 5; animation: drift 28s linear infinite; }
      @keyframes drift { to { stroke-dashoffset: -200 } }

      /* aurora ribbon shimmer */
      .map-aurora .aurora-ribbon { animation: auroraShift 14s ease-in-out infinite; transform-origin: center; }
      @keyframes auroraShift {
        0%,100% { transform: translate(0,0) scaleY(1);   opacity: .85 }
        50%     { transform: translate(0,-10px) scaleY(1.15); opacity: 1 }
      }

      /* tidal ocean: slowly slide the linear gradient angle */
      .map-tidal .ocean-fill { animation: tideHue 18s ease-in-out infinite; }
      @keyframes tideHue {
        0%,100% { filter: hue-rotate(0deg) saturate(1) }
        50%     { filter: hue-rotate(-12deg) saturate(1.15) }
      }

      /* watercolor: very subtle breathing on the land wash */
      .map-watercolor .land-fill { animation: breathe 12s ease-in-out infinite; }
      @keyframes breathe { 0%,100% { opacity: .92 } 50% { opacity: 1 } }

      /* psychedelic ocean: drifting caustic light reflections.
         Three soft-blurred radial-blob layers move at different speeds,
         blended with mix-blend "screen" so they shimmer over the dark
         ocean of the base style without painting over light land areas. */
      .psy-layer {
        position: absolute; inset: -12%;
        pointer-events: none; z-index: 2;
        mix-blend-mode: screen;
        filter: blur(34px) saturate(1.05);
      }
      .psy-a {
        background:
          radial-gradient(ellipse 38% 30% at 18% 32%, rgba(28,240,255,0.65) 0%, transparent 60%),
          radial-gradient(ellipse 32% 26% at 72% 64%, rgba(255,62,201,0.5)  0%, transparent 60%),
          radial-gradient(ellipse 28% 22% at 88% 22%, rgba(255,209,102,0.45) 0%, transparent 60%);
        animation: causticA 26s ease-in-out infinite alternate;
      }
      .psy-b {
        background:
          radial-gradient(ellipse 36% 28% at 60% 78%, rgba(98,232,212,0.55) 0%, transparent 60%),
          radial-gradient(ellipse 30% 24% at 28% 82%, rgba(165,135,255,0.5) 0%, transparent 60%),
          radial-gradient(ellipse 22% 18% at 82% 44%, rgba(255,255,255,0.30) 0%, transparent 60%);
        animation: causticB 34s ease-in-out infinite alternate;
      }
      .psy-c {
        background:
          radial-gradient(ellipse 18% 14% at 44% 50%, rgba(255,255,255,0.35) 0%, transparent 65%),
          radial-gradient(ellipse 14% 12% at 22% 64%, rgba(180,255,240,0.40) 0%, transparent 65%),
          radial-gradient(ellipse 12% 10% at 74% 30%, rgba(255,220,200,0.32) 0%, transparent 65%);
        animation: causticC 18s ease-in-out infinite alternate;
        filter: blur(20px) saturate(1.1);
      }
      @keyframes causticA {
        0%   { transform: translate(0, 0) scale(1) }
        50%  { transform: translate(-4%, 3%) scale(1.08) }
        100% { transform: translate(3%, -2%) scale(1.04) }
      }
      @keyframes causticB {
        0%   { transform: translate(0, 0) scale(1) }
        50%  { transform: translate(4%, -3%) scale(1.07) }
        100% { transform: translate(-3%, 2%) scale(0.97) }
      }
      @keyframes causticC {
        0%   { transform: translate(0, 0) scale(1) }
        50%  { transform: translate(-2%, -3%) scale(1.12) }
        100% { transform: translate(2%, 2%) scale(0.95) }
      }

      /* MapLibre attribution & control buttons should not steal map cursor on hover */
      .maplibregl-ctrl, .maplibregl-ctrl-attrib { font-family: ${T.body}; }

      input[type=range] { height: 22px; }
      textarea, input { font-family: ${T.body}; }
      audio { filter: invert(0.9) hue-rotate(180deg); }
    `}</style>
  );
}
